      expect(result.exitCode, result.stderr).toBe(accepted ? 0 : 1);
      expect(result.stderr).toContain(`[${accepted ? 'PASS' : 'FAIL'}] plan task mapping is valid`);
      expect(await fs.readFile(planFile, 'utf8')).toBe(plan);
