    expect(result.stderr).toContain('检查未通过，退出码 7');
    expect(result.stderr).not.toContain('guard auto-ran');

    await fs.writeFile(marker, 'ready\n');
    const rerun = await platformCheck(cli, dir, 'demo', 'build', [
      process.execPath,
      '-e',
      code,
      ...exactArgs,
    ]);
    expect(rerun.exitCode, rerun.stderr).toBe(0);
  });

  it('does not print legacy JSON argv as a shell recovery command', async () => {
    const dir = await makeProject();
    const cli = (...args: string[]) =>
      withClassicCommandContext({ projectRoot: dir, invocationCwd: dir }, () =>
        runClassicCli(args),
      );
    expect(
      (
        await cli(
          'state',
          'init',
          'legacy-argv',
          'hotfix',
          '--isolation',
          'current',
          '--runtime',
          'compat',
        )
      ).exitCode,
    ).toBe(0);
    const changeDir = path.join(dir, 'openspec/changes/legacy-argv');
    const stateFile = path.join(changeDir, '.comet.yaml');
    const state = parse(await fs.readFile(stateFile, 'utf8'));
    await fs.writeFile(stateFile, stringify({ ...state, phase: 'build' }));
    await fs.writeFile(path.join(changeDir, 'tasks.md'), '- [x] work <!-- comet-task:a -->\n');
    await fs.writeFile(path.join(changeDir, 'proposal.md'), '# Proposal\n');
    expect(
      (
        await platformCheck(cli, dir, 'legacy-argv', 'build', [
          process.execPath,
          '-e',
          'process.exit(0)',
        ])
      ).exitCode,
    ).toBe(0);
    const legacyArgv = JSON.stringify([process.execPath, '-e', 'process.exit(7)']);
    expect(spawnSync(process.execPath, ['-e', 'process.exit(7)'], { cwd: dir }).status).toBe(7);
    expect(
      (
        await cli(
          'state',
          'record-check',
          'legacy-argv',
          'build',
          '--command',
          legacyArgv,
          '--exit-code',
          '7',
        )
      ).exitCode,
    ).toBe(0);

    const result = await cli('guard', 'legacy-argv', 'build');
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain('检查未通过，退出码 7');
    expect(result.stderr).not.toContain(
      `Next: comet check run legacy-argv build --local -- ${legacyArgv}`,
    );
  });

  it('blocks the open guard when artifacts are missing and leaves state unchanged', async () => {
    const dir = await makeProject();
    expect(run(dir, 'state', 'init', 'demo', 'full', '--runtime', 'compat').status).toBe(0);

    const result = run(dir, 'guard', 'demo', 'open');
    expect(result.status).toBe(1);
    expect(result.stderr).toContain('[FAIL] proposal.md exists and non-empty');
    expect(result.stderr).toContain('[FAIL] tasks.md has at least one task');
    expect(result.stderr).toContain('BLOCKED — fix failing checks before proceeding to next phase');

    // A blocked guard must not mutate state.
    expect(run(dir, 'state', 'get', 'demo', 'phase').stdout.trim()).toBe('open');

    const stateFile = path.join(dir, 'openspec', 'changes', 'demo', '.comet.yaml');
    const migrated = await fs.readFile(stateFile, 'utf8');
    const second = run(dir, 'guard', 'demo', 'open');
    expect(second.status).toBe(1);
    expect(await fs.readFile(stateFile, 'utf8')).toBe(migrated);
  });

  it('passes the open guard and applies the transition when artifacts exist', async () => {
    const dir = await makeProject();
    run(dir, 'state', 'init', 'demo', 'hotfix', '--runtime', 'compat');
    run(dir, 'state', 'set', 'demo', 'isolation', 'branch');
    const changeDir = path.join(dir, 'openspec', 'changes', 'demo');
    await fs.writeFile(path.join(changeDir, 'proposal.md'), 'proposal\n');
    await fs.writeFile(path.join(changeDir, 'design.md'), 'design\n');
    await fs.writeFile(path.join(changeDir, 'tasks.md'), '- [x] implement guard\n');

    const result = run(dir, 'guard', 'demo', 'open', '--apply');
    expect(result.status).toBe(0);
    expect(result.stderr).toContain('ALL CHECKS PASSED — ready for next phase');
    expect(result.stderr).toContain('[APPLY] .comet.yaml updated: phase=build');
    expect(run(dir, 'state', 'get', 'demo', 'phase').stdout.trim()).toBe('build');

    const state = parse(await fs.readFile(path.join(changeDir, '.comet.yaml'), 'utf8')) as Record<
      string,
      unknown
    >;
    expect(state).toMatchObject({
      classic_profile: 'hotfix',
      classic_migration: 1,
    });
    const runState = await readRunState(await resolveClassicRunDirectory(changeDir));
    expect(runState).not.toBeNull();
    expect(runState!.skill).toBe('comet-classic');
    expect(runState!.currentStep).toBe('hotfix.build.complete');
    expect(runState!.iteration).toBe(1);
    const eventLog = await fs.readFile(
      path.join(changeDir, '.comet', 'state-events.jsonl'),
      'utf8',
    );
    expect(JSON.parse(eventLog.trim())).toMatchObject({
      schemaVersion: 1,
      change: 'demo',
      event: 'open-complete',
      source: 'comet-guard',
      from: { workflow: 'hotfix', phase: 'open' },
      to: { workflow: 'hotfix', phase: 'build' },
      effects: [
        { field: 'checkEpoch', to: 1 },
        { field: 'phase', from: 'open', to: 'build' },
      ],
    });
    const trajectory = (
      await fs.readFile(
        path.join(await resolveClassicRunDirectory(changeDir), runState!.trajectoryRef),
        'utf8',
      )
    )
      .trim()
      .split(/\r?\n/u)
      .map((line) => JSON.parse(line) as { type: string });
    expect(trajectory.filter((event) => event.type === 'state_transitioned')).toHaveLength(1);
  });

  it.each(['docs/superpowers/specs/demo-design.md', 'openspec/changes/demo/design.md'])(
    'resolves delta specs from nested cwd with design authority %s',
    async (designPath) => {
      const dir = await makeProject();
      expect(run(dir, 'state', 'init', 'demo', 'full', '--runtime', 'compat').status).toBe(0);

      const changeDir = path.join(dir, 'openspec', 'changes', 'demo');
      await fs.mkdir(path.join(changeDir, 'specs', 'feature'), { recursive: true });
      await fs.writeFile(path.join(changeDir, 'proposal.md'), '# Proposal\n');
      await fs.writeFile(path.join(changeDir, 'design.md'), '# Design\n');
      await fs.writeFile(path.join(changeDir, 'tasks.md'), '- [x] implement guard\n');
      await fs.writeFile(path.join(changeDir, 'specs', 'feature', 'spec.md'), '# Feature\n');
      await fs.mkdir(path.join(dir, 'docs', 'superpowers', 'specs'), { recursive: true });
      await fs.writeFile(
        path.join(dir, designPath),
        [
          '---',
          'comet_change: demo',
          'role: technical-design',
          'canonical_spec: openspec',
          '---',
          '',
          '# Design',
          '',
        ].join('\n'),
      );

      expect(run(dir, 'state', 'set', 'demo', 'phase', 'design').status).toBe(0);
      expect(run(dir, 'state', 'set', 'demo', 'design_doc', designPath).status).toBe(0);
      expect(run(dir, 'handoff', 'demo', 'design', '--write').status).toBe(0);

      const nestedCwd = path.join(dir, 'agent', 'workspace');
      await fs.mkdir(nestedCwd, { recursive: true });
      const result = run(nestedCwd, 'guard', 'demo', 'design', '--apply');

      expect(result.status, result.stderr).toBe(0);
      expect(result.stderr).toContain('ALL CHECKS PASSED — ready for next phase');
      expect(result.stderr).not.toContain('ENOENT: no such file or directory, scandir');
      expect(run(dir, 'state', 'get', 'demo', 'phase').stdout.trim()).toBe('build');
    },
  );

  it('fails closed for an unknown phase without running checks', async () => {
    const dir = await makeProject();
    run(dir, 'state', 'init', 'demo', 'full', '--runtime', 'compat');

    const result = run(dir, 'guard', 'demo', 'lint');
    expect(result.status).not.toBe(0);
    expect(result.stderr).toContain('Unknown phase: lint');
    expect(result.stderr).toContain('Valid phases: open, design, build, verify, archive');
  });

  it('returns resolver diagnostics in json mode', async () => {
    const dir = await makeProject();
    expect(run(dir, 'state', 'init', 'demo', 'full', '--runtime', 'compat').status).toBe(0);
    await fs.writeFile(
      path.join(dir, 'openspec', 'changes', 'demo', 'proposal.md'),
      '# Proposal\n',
    );
    await fs.writeFile(path.join(dir, 'openspec', 'changes', 'demo', 'design.md'), '# Design\n');
    await fs.writeFile(path.join(dir, 'openspec', 'changes', 'demo', 'tasks.md'), '- [ ] build\n');

    const result = run(dir, 'guard', 'demo', 'open', '--json');
    const wrapper = JSON.parse(result.stdout);
    const payload = JSON.parse(wrapper.stdout);

    expect(payload.diagnostics).toMatchObject({
      change: 'demo',
      phase: 'open',
      currentStep: 'full.open',
      runtimeEval: { stepId: 'full.open' },
    });
  });
});

import { execFileSync, spawnSync } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, expect, it, vi } from 'vitest';
import { createOpenSpecArchiveFixture } from '../../helpers/classic-openspec-fixture.js';
import { canRepairClassicDelivery } from '../../../domains/comet-classic/classic-sdk-delivery-repair-model.js';
import { inspectClassicSdkRun } from '../../../domains/comet-classic/classic-sdk-status.js';
import { prepareClassicLegacyProject } from '../../helpers/classic-project.js';

const roots: string[] = [];
afterEach(async () => {
  await Promise.all(
    roots
      .splice(0)
      .map((root) => fs.rm(root, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 })),
  );
});

it('repairs archived Classic v2 delivery with platform reports without replaying commands or Archive', async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-agent-checks-'));
  roots.push(root);
  await prepareClassicLegacyProject(root);
  execFileSync('git', ['init', '-b', 'main'], { cwd: root, stdio: 'ignore' });
  execFileSync(
    'git',
    [
      '-c',
      'user.name=Test',
      '-c',
      'user.email=test@example.invalid',
      'commit',
      '--allow-empty',
      '-m',
      'base',
    ],
    { cwd: root, stdio: 'ignore' },
  );
  const cli = async (...args: string[]) => {
    const result = spawnSync(
      process.execPath,
      [
        path.resolve('assets/skills/comet/scripts/comet-runtime.mjs'),
        args[0],
        '--json',
        ...args.slice(1),
      ],
      {
        cwd: root,
        encoding: 'utf8',
        windowsHide: true,
      },
    );
    return JSON.parse(result.stdout!);
  };
  const initialized = await cli('state', 'init', 'example', 'hotfix', '--isolation', 'current');
  expect(initialized.exitCode, initialized.stderr).toBe(0);
  const dir = path.join(root, 'openspec/changes/example');
  await fs.writeFile(path.join(dir, 'proposal.md'), '# Proposal\nFix a small defect.\n');
  await fs.writeFile(path.join(dir, 'design.md'), '# Design\nKeep the existing scope.\n');
  await fs.writeFile(path.join(dir, 'tasks.md'), '- [ ] Implement the change\n');
  const preview = await cli('guard', 'example', 'open');
  const opened = await cli(
    'guard',
    'example',
    'open',
    '--apply',
    '--approval-hash',
    preview.data.approvalHash,
  );
  expect(opened.exitCode, opened.stderr).toBe(0);
  await fs.writeFile(path.join(dir, 'tasks.md'), '- [x] Implement the change\n');
  await fs.writeFile(
    path.join(root, 'checks.json'),
    JSON.stringify({ checks: [{ name: 'Actual platform command exited 7', result: 'failed' }] }),
  );
  const before = (await inspectClassicSdkRun(root, 'example')).run;
  const managed = await cli(
    'check',
    'run',
    'example',
    'build',
    '--',
    process.execPath,
    '-e',
    'process.exit(0)',
  );
  expect(managed.exitCode).toBe(0);
  expect(managed.data).toMatchObject({
    status: 'platform-execution-required',
    checksExecuted: false,
  });
  expect((await inspectClassicSdkRun(root, 'example')).run).toEqual(before);
  const rejected = await cli('state', 'complete-build', 'example', '--checks', 'checks.json');
  expect(rejected.exitCode).not.toBe(0);
  expect((await inspectClassicSdkRun(root, 'example')).run).toEqual(before);
  await fs.writeFile(
    path.join(root, 'checks.json'),
    JSON.stringify({
      checks: [
        {
          name: 'Generate required output',
          result: 'passed',
          note: 'Actual platform Node command created generated/check-output.bin in projectRoot.',
        },
      ],
    }),
  );
  execFileSync(
    process.execPath,
    [
      '-e',
      "const fs=require('node:fs');fs.mkdirSync('generated',{recursive:true});fs.writeFileSync('generated/check-output.bin','actual output');",
    ],
    { cwd: root },
  );
  const completed = await cli('state', 'complete-build', 'example', '--checks', 'checks.json');
  expect(completed.exitCode, completed.stderr).toBe(0);
  const next = (await inspectClassicSdkRun(root, 'example')).run;
  expect(next.workflow.version).toBe('2');
  expect(next.actions.some((action) => action.stepId.endsWith('.build.check'))).toBe(false);
  expect(next.actions.find((action) => action.status === 'pending')?.stepId).toBe(
    'hotfix.verify.run',
  );
  expect(completed.data.checksMode).toBe('agent');
  const reportRef = 'docs/superpowers/reports/example.md';
  await fs.mkdir(path.dirname(path.join(root, reportRef)), { recursive: true });
  await fs.writeFile(
    path.join(root, reportRef),
    '# Verification\nAll scoped acceptance items were reviewed.\n',
  );
  const verified = await cli(
    'guard',
    'example',
    'verify',
    '--report',
    reportRef,
    '--apply',
    '--checks',
    'checks.json',
  );
  expect(verified.exitCode, verified.stderr).toBe(0);
  const final = (await inspectClassicSdkRun(root, 'example')).run;
  expect((final.state as { phase: string }).phase).toBe('archive');
  expect(final.actions.some((action) => action.stepId.endsWith('.verify.check'))).toBe(false);
  expect(final.actions.find((action) => action.status === 'pending')?.stepId).toBe(
    'hotfix.archive.prepare',
  );
  await fs.writeFile(
    path.join(root, '.comet/check-policy.json'),
    JSON.stringify({
      version: 2,
      commands: [
        {
          argv: [
            process.execPath,
            '-e',
            "const fs=require('node:fs');fs.mkdirSync('generated',{recursive:true});fs.writeFileSync('generated/check-output.bin','actual output');",
          ],
          cwd: '.',
          outputs: ['generated/**'],
        },
      ],
    }),
  );
  const fixtureRoot = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-agent-repair-tool-'));
  roots.push(fixtureRoot);
  const openSpec = await createOpenSpecArchiveFixture(fixtureRoot);
  vi.stubEnv('COMET_OPENSPEC', openSpec.command);
  const proposal = await cli(
    'state',
    'propose-archive',
    'example',
    '--summary',
    'Fixture user approves local delivery.',
  );
  expect(proposal.exitCode, proposal.stderr).toBe(0);
  const approval = await cli(
    'state',
    'decide-archive',
    'example',
    '--proposal-hash',
    proposal.data.wait.proposalHash,
    '--choice',
    'local',
  );
  expect(approval.exitCode, approval.stderr).toBe(0);
  const archived = await cli('guard', 'example', 'archive', '--apply');
  expect(archived.exitCode, JSON.stringify(archived)).toBe(0);
  const original = (await inspectClassicSdkRun(root, 'example')).run;
  expect(original.workflow.version).toBe('2');
  expect(canRepairClassicDelivery(original)).toBe(true);
  await fs.unlink(path.join(root, 'generated/check-output.bin'));
  const missing = await cli(
    'state',
    'repair-delivery',
    'example',
    '--expected-revision',
    String(original.revision),
  );
  expect(missing.exitCode).not.toBe(0);
  expect((await inspectClassicSdkRun(root, 'example')).run).toEqual(original);
  await fs.writeFile(
    path.join(root, 'failed.json'),
    JSON.stringify({ checks: [{ name: 'Real failed check', result: 'failed' }] }),
  );
  const failed = await cli(
    'state',
    'repair-delivery',
    'example',
    '--expected-revision',
    String(original.revision),
    '--checks',
    'failed.json',
  );
  expect(failed.exitCode).not.toBe(0);
  expect((await inspectClassicSdkRun(root, 'example')).run).toEqual(original);
  // The platform regenerates the output; Runtime must never execute the policy command.
  await fs.writeFile(path.join(root, 'generated/check-output.bin'), 'platform regenerated');
  const repair = await cli(
    'state',
    'repair-delivery',
    'example',
    '--expected-revision',
    String(original.revision),
    '--checks',
    'checks.json',
  );
  const after = (await inspectClassicSdkRun(root, 'example')).run;
  expect(repair.exitCode, JSON.stringify(repair)).toBe(0);
  expect(after.runId).toBe(original.runId);
  expect(after.workflow.version).toBe('2');
  expect(await openSpec.invocations()).toHaveLength(1);
  expect(after.actions.filter((a) => a.stepId.endsWith('.verify.check'))).toEqual([]);
  const continued = await cli('state', 'next', 'example', '--continue');
  expect(
    continued.exitCode,
    JSON.stringify((await inspectClassicSdkRun(root, 'example')).run.actions.at(-1)),
  ).toBe(0);
  const waiting = (await inspectClassicSdkRun(root, 'example')).run;
  const decision = waiting.waits.find((w) => w.status === 'pending')!;
  expect(decision.stepId).toBe('hotfix.delivery.confirm');
  expect(
    (
      await cli(
        'state',
        'complete-delivery',
        'example',
        '--commit',
        execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim(),
      )
    ).exitCode,
  ).not.toBe(0);
  expect((await inspectClassicSdkRun(root, 'example')).run).toEqual(waiting);
  expect(
    (
      await cli(
        'state',
        'decide-delivery-repair',
        'example',
        '--proposal-hash',
        decision.proposalHash,
        '--choice',
        'approved',
      )
    ).exitCode,
  ).toBe(0);
  expect(await fs.readFile(path.join(root, 'generated/check-output.bin'), 'utf8')).toBe(
    'platform regenerated',
  );
  const archiveRef = (
    original.outputs['hotfix.archive.execute'].value as { archiveDirectory: string }
  ).archiveDirectory;
  execFileSync(
    'git',
    ['add', '--', archiveRef, reportRef, 'generated/check-output.bin', 'checks.json'],
    { cwd: root },
  );
  execFileSync(
    'git',
    ['-c', 'user.name=Test', '-c', 'user.email=test@example.invalid', 'commit', '-m', 'deliver'],
    { cwd: root, stdio: 'ignore' },
  );
  const sha = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim();
  const delivered = await cli('state', 'complete-delivery', 'example', '--commit', sha);
  expect(delivered.exitCode, JSON.stringify(delivered)).toBe(0);
  expect((await inspectClassicSdkRun(root, 'example')).run.status).toBe('completed');
  expect(await openSpec.invocations()).toHaveLength(1);
  vi.unstubAllEnvs();
});
